        "question": "(1) Oyuncaklarını topladı. (2) Ödevlerini bitirdi. (3) Arkadaşlarıyla parka gitti.\n\"Zeynep önce ödevlerini bitirdi, sonra oyuncaklarını topladı ve en sonunda arkadaşlarıyla parka gitti.\" diyen biri yukarıdaki olayları hangi sırayla dizmiştir?",
